    "Alejado del paisaje tradicional del valle, Quintay ofrece una experiencia marcada por el océano, sus paisajes costeros y una memoria profundamente vinculada a las actividades marítimas. Es un lugar para recorrer con calma, conocer su patrimonio y acercarse a la vida de una comunidad que mantiene una estrecha relación con el mar.": "Away from the valley's traditional landscape, Quintay offers an experience shaped by the ocean, coastal scenery and a history closely tied to maritime life. Take your time to explore its heritage and discover a community with a deep connection to the sea.",
