    "El carácter": "The character",
    "del valle.": "of the valley.",
    "Un territorio donde la influencia del océano, la naturaleza y la tradición vitivinícola dan forma a un paisaje único.": "A region shaped by the influence of the ocean, nature and a long winemaking tradition.",
    "Descubrir el valle": "Discover the valley",
    "UNA IDENTIDAD RECONOCIDA": "A RECOGNISED IDENTITY",
    "Mucho más que": "More than",
    "una copa de vino.": "a glass of wine.",
    "Ubicado en la Región de Valparaíso, el Valle de Casablanca se ha consolidado como uno de los territorios vitivinícolas más reconocidos de Chile, especialmente por la producción de vinos de clima fresco.": "Located in the Valparaíso Region, the Casablanca Valley has become one of Chile's best-known wine regions, particularly for its cool-climate wines.",
    "Su identidad está estrechamente relacionada con la cercanía del océano Pacífico, sus paisajes de colinas y la actividad agrícola que forma parte de la historia de la comuna.": "Its identity is closely tied to the nearby Pacific Ocean, rolling landscapes and the agricultural activity that has long been part of the commune's history.",
    "Aquí, la vitivinicultura convive con la gastronomía, la naturaleza y las tradiciones del mundo rural.": "Here, winemaking goes hand in hand with gastronomy, nature and rural traditions.",
    "EL VALLE Y SU ENTORNO": "THE VALLEY AND ITS SURROUNDINGS",
    "La influencia": "The influence",
    "del océano.": "of the ocean.",
    "Una de las características más importantes del Valle de Casablanca es su proximidad al océano Pacífico. Esta influencia marítima contribuye a moderar las temperaturas y generar condiciones favorables para el cultivo de variedades que se desarrollan mejor en climas frescos.": "One of the Casablanca Valley's defining features is its proximity to the Pacific Ocean. The maritime influence moderates temperatures and creates favourable conditions for grape varieties that thrive in cooler climates.",
    "Las mañanas frescas, las neblinas costeras y las diferencias de temperatura durante el día forman parte de las condiciones que distinguen a este territorio.": "Cool mornings, coastal fog and temperature shifts throughout the day are among the conditions that make this region distinctive.",
    "Estas características pueden favorecer una maduración más pausada de las uvas y la conservación de su acidez natural, cualidades especialmente apreciadas en determinados estilos de vinos blancos y tintos.": "These conditions can encourage slower grape ripening and preserve natural acidity—qualities valued in certain styles of both white and red wine.",
    "UN TERRITORIO CON PERSONALIDAD": "A REGION WITH CHARACTER",
    "¿Qué hace especial al valle?": "What makes the valley special?",
    "La combinación de factores naturales y el trabajo vitivinícola han contribuido a construir la identidad de Casablanca.": "A combination of natural conditions and winemaking expertise has shaped Casablanca's identity.",
    "Clima costero": "Coastal climate",
    "La cercanía del océano Pacífico ayuda a moderar las temperaturas, creando condiciones adecuadas para variedades de clima fresco.": "The nearby Pacific Ocean moderates temperatures, creating suitable conditions for cool-climate grape varieties.",
    "Neblinas matinales": "Morning fog",
    "La presencia de nieblas y mañanas frescas forma parte del entorno climático que caracteriza a distintos sectores del valle.": "Fog and cool mornings are part of the climate in several areas of the valley.",
    "Diversidad de suelos": "Diverse soils",
    "Los distintos terrenos y condiciones de cultivo permiten que cada sector presente características particulares para el desarrollo de las vides.": "Different soils and growing conditions give each area its own characteristics for vine cultivation.",
    "Tradición vitivinícola": "Winemaking tradition",
    "La experiencia de sus productores y el desarrollo de técnicas de cultivo y elaboración han fortalecido la identidad del valle.": "Local producers' expertise and evolving growing and winemaking techniques have strengthened the valley's identity.",
    "VINO Y TERRITORIO": "WINE AND PLACE",
    "Sabores que expresan": "Flavours that reflect",
    "el paisaje.": "the landscape.",
    "Casablanca destaca especialmente por sus variedades blancas, aunque también cuenta con una producción de vinos tintos que aprovecha las condiciones de sus distintos sectores.": "Casablanca is particularly known for its white varieties, while its red wines also benefit from the distinct conditions found across the valley.",
    "Cada variedad posee características propias y puede expresar diferentes aromas, sabores y estructuras dependiendo del clima, el suelo y el proceso de elaboración.": "Each variety has its own character and can express different aromas, flavours and structures depending on the climate, soil and winemaking process.",
