    "Las indicaciones son orientativas. Antes de viajar, confirma los recorridos, horarios, tarifas, puntos de salida y disponibilidad directamente con los operadores correspondientes.": "As indicações são orientativas. Antes de viajar, confirme itinerários, horários, tarifas, pontos de partida e disponibilidade diretamente com as operadoras.",
