    "Continúa explorando": "Continue explorando",
    "la comuna.": "o município.",
    "Si llegas a Casablanca y quieres visitar Quintay, las viñas u otros sectores rurales, organiza con anticipación los traslados entre localidades.": "Se chegar a Casablanca e quiser visitar Quintay, as vinícolas ou outras áreas rurais, planeje com antecedência os deslocamentos entre as localidades.",
    "La disponibilidad de transporte local puede variar según el día, la temporada y el sector que quieras visitar.": "A disponibilidade de transporte local pode variar conforme o dia, a temporada e a região que deseja visitar.",
