    "Quintay,": "Quintay,",
    "mirada al mar.": "de frente para o mar.",
    "Una costa de paisajes, historias y tradiciones que forman parte de la identidad de Casablanca.": "Um litoral de paisagens, histórias e tradições que fazem parte da identidade de Casablanca.",
    "OTRA FORMA DE VIVIR CASABLANCA": "OUTRO JEITO DE VIVER CASABLANCA",
    "Donde la historia": "Onde a história",
    "se encuentra con el océano.": "encontra o oceano.",
    "Alejado del paisaje tradicional del valle, Quintay ofrece una experiencia marcada por el océano, sus paisajes costeros y una memoria profundamente vinculada a las actividades marítimas. Es un lugar para recorrer con calma, conocer su patrimonio y acercarse a la vida de una comunidad que mantiene una estrecha relación con el mar.": "Longe da paisagem tradicional do vale, Quintay oferece uma experiência marcada pelo oceano, pelas paisagens costeiras e por uma memória profundamente ligada às atividades marítimas. É um lugar para conhecer com calma seu patrimônio e a vida de uma comunidade que mantém uma forte relação com o mar.",
    "Sus playas, espacios patrimoniales y expresiones locales permiten descubrir otra faceta de la comuna de Casablanca.": "Suas praias, espaços patrimoniais e expressões locais revelam outra faceta do município de Casablanca.",
    "ENTRE EL VALLE Y EL MAR": "ENTRE O VALE E O MAR",
    "Un territorio": "Um território",
    "con identidad propia.": "com identidade própria.",
    "Quintay representa una dimensión distinta del territorio de Casablanca. Su paisaje, sus actividades tradicionales y su historia marítima complementan la identidad rural y vitivinícola del interior de la comuna.": "Quintay representa uma dimensão diferente do território de Casablanca. Sua paisagem, atividades tradicionais e história marítima complementam a identidade rural e vitivinícola do interior do município.",
    "Visitar este sector es también una oportunidad para reconocer el valor de sus espacios naturales, su patrimonio y las personas que forman parte de su historia.": "Visitar esta região também é uma oportunidade de reconhecer o valor de seus espaços naturais, patrimônio e das pessoas que fazem parte dessa história.",
