    "Playa Grande y Playa Chica.": "Playa Grande e Playa Chica.",
    "Dos espacios representativos del paisaje costero de Quintay. Sus entornos permiten disfrutar del océano, contemplar el paisaje y recorrer el borde costero con tranquilidad.": "Dois espaços representativos do litoral de Quintay. Aproveite o oceano, contemple a paisagem e caminhe com tranquilidade pela orla.",
    "Antes de ingresar al agua, revisa las condiciones del mar, las señalizaciones y las recomendaciones de seguridad vigentes.": "Antes de entrar na água, confira as condições do mar, a sinalização e as recomendações de segurança atuais.",
    "Naturaleza y contemplación": "Natureza e contemplação",
    "La información presentada es orientativa. Las condiciones de acceso y disponibilidad de actividades pueden variar.": "As informações são orientativas. As condições de acesso e a disponibilidade de atividades podem variar.",
    "VIVE LA EXPERIENCIA": "VIVA A EXPERIÊNCIA",
    "Mucho más que": "Muito mais que",
    "un destino costero.": "um destino costeiro.",
    "Quintay ofrece distintas formas de disfrutar el territorio, siempre desde el respeto por su entorno y comunidad.": "Quintay oferece diferentes maneiras de aproveitar a região, sempre com respeito ao meio ambiente e à comunidade.",
    "Paisajes y naturaleza.": "Paisagens e natureza.",
    "Contempla el océano, recorre los espacios costeros habilitados y disfruta de los paisajes que caracterizan este sector.": "Contemple o oceano, percorra as áreas costeiras autorizadas e aproveite as paisagens que caracterizam a região.",
    "Historia y patrimonio.": "História e patrimônio.",
