    "Cuidado del entorno": "Cuide do ambiente",
    "Evita dejar residuos y respeta los espacios naturales y señalizaciones.": "Não deixe resíduos e respeite as áreas naturais e a sinalização.",
    "Planifica tu visita": "Planeje sua visita",
    "Confirma horarios, condiciones de acceso y disponibilidad de servicios antes de viajar.": "Confirme horários, condições de acesso e disponibilidade de serviços antes de viajar.",
    "Respeta a la comunidad": "Respeite a comunidade",
    "Mantén una actitud responsable con los residentes y las actividades locales.": "Aja com responsabilidade em relação aos moradores e às atividades locais.",
