    "HISTORIAS ENTRE EL VALLE Y EL MAR": "HISTÓRIAS ENTRE O VALE E O MAR",
    "Casablanca también": "Casablanca também",
    "se descubre desde": "se descobre pelo",
    "el océano.": "oceano.",
    "Continúa explorando los paisajes, la historia y las experiencias que ofrece la comuna.": "Continue explorando as paisagens, a história e as experiências que o município oferece.",
    "Planificar mi visita": "Planejar minha visita",
    "Explorar la historia de Casablanca": "Explore a história de Casablanca",
    "VALLE · VINO · NATURALEZA": "VALE · VINHO · NATUREZA",
    "El carácter": "A essência",
    "del valle.": "do vale.",
    "Un territorio donde la influencia del océano, la naturaleza y la tradición vitivinícola dan forma a un paisaje único.": "Um território onde a influência do oceano, a natureza e a tradição vitivinícola dão forma a uma paisagem única.",
    "Descubrir el valle": "Descubra o vale",
    "UNA IDENTIDAD RECONOCIDA": "UMA IDENTIDADE RECONHECIDA",
    "Mucho más que": "Muito mais que",
    "una copa de vino.": "uma taça de vinho.",
    "Ubicado en la Región de Valparaíso, el Valle de Casablanca se ha consolidado como uno de los territorios vitivinícolas más reconocidos de Chile, especialmente por la producción de vinos de clima fresco.": "Localizado na Região de Valparaíso, o Vale de Casablanca se tornou uma das regiões vitivinícolas mais reconhecidas do Chile, especialmente pela produção de vinhos de clima frio.",
    "Su identidad está estrechamente relacionada con la cercanía del océano Pacífico, sus paisajes de colinas y la actividad agrícola que forma parte de la historia de la comuna.": "Sua identidade está ligada à proximidade do oceano Pacífico, às paisagens de colinas e à atividade agrícola que faz parte da história do município.",
    "Aquí, la vitivinicultura convive con la gastronomía, la naturaleza y las tradiciones del mundo rural.": "Aqui, a vitivinicultura convive com a gastronomia, a natureza e as tradições rurais.",
    "EL VALLE Y SU ENTORNO": "O VALE E SEU ENTORNO",
    "La influencia": "A influência",
    "del océano.": "do oceano.",
    "Una de las características más importantes del Valle de Casablanca es su proximidad al océano Pacífico. Esta influencia marítima contribuye a moderar las temperaturas y generar condiciones favorables para el cultivo de variedades que se desarrollan mejor en climas frescos.": "Uma das principais características do Vale de Casablanca é a proximidade do oceano Pacífico. A influência marítima ajuda a moderar as temperaturas e cria condições favoráveis ao cultivo de variedades que se desenvolvem melhor em climas frios.",
    "Las mañanas frescas, las neblinas costeras y las diferencias de temperatura durante el día forman parte de las condiciones que distinguen a este territorio.": "As manhãs frescas, a neblina costeira e as variações de temperatura ao longo do dia são características deste território.",
    "Estas características pueden favorecer una maduración más pausada de las uvas y la conservación de su acidez natural, cualidades especialmente apreciadas en determinados estilos de vinos blancos y tintos.": "Essas condições podem favorecer a maturação gradual das uvas e preservar sua acidez natural, características valorizadas em determinados estilos de vinhos brancos e tintos.",
    "UN TERRITORIO CON PERSONALIDAD": "UM TERRITÓRIO COM PERSONALIDADE",
    "¿Qué hace especial al valle?": "O que torna o vale especial?",
    "La combinación de factores naturales y el trabajo vitivinícola han contribuido a construir la identidad de Casablanca.": "A combinação de fatores naturais e do trabalho vitivinícola contribuiu para construir a identidade de Casablanca.",
    "Clima costero": "Clima costeiro",
    "La cercanía del océano Pacífico ayuda a moderar las temperaturas, creando condiciones adecuadas para variedades de clima fresco.": "A proximidade do oceano Pacífico ajuda a moderar as temperaturas e cria condições adequadas para variedades de clima frio.",
    "Neblinas matinales": "Neblinas matinais",
    "La presencia de nieblas y mañanas frescas forma parte del entorno climático que caracteriza a distintos sectores del valle.": "A presença de neblina e de manhãs frescas caracteriza o clima de diferentes áreas do vale.",
    "Diversidad de suelos": "Diversidade de solos",
    "Los distintos terrenos y condiciones de cultivo permiten que cada sector presente características particulares para el desarrollo de las vides.": "Os diferentes terrenos e condições de cultivo conferem características próprias a cada área para o desenvolvimento das videiras.",
    "Tradición vitivinícola": "Tradição vitivinícola",
    "La experiencia de sus productores y el desarrollo de técnicas de cultivo y elaboración han fortalecido la identidad del valle.": "A experiência dos produtores e o desenvolvimento de técnicas de cultivo e produção fortaleceram a identidade do vale.",
    "VINO Y TERRITORIO": "VINHO E TERRITÓRIO",
    "Sabores que expresan": "Sabores que expressam",
    "el paisaje.": "a paisagem.",
    "Casablanca destaca especialmente por sus variedades blancas, aunque también cuenta con una producción de vinos tintos que aprovecha las condiciones de sus distintos sectores.": "Casablanca se destaca especialmente pelas variedades brancas, mas também produz vinhos tintos que aproveitam as condições de diferentes áreas.",
    "Cada variedad posee características propias y puede expresar diferentes aromas, sabores y estructuras dependiendo del clima, el suelo y el proceso de elaboración.": "Cada variedade tem características próprias e pode expressar diferentes aromas, sabores e estruturas conforme o clima, o solo e o processo de produção.",
