    "Vinos que identifican a Casablanca.": "Vinhos que representam Casablanca.",
    "Explora algunas de las variedades que han contribuido al reconocimiento vitivinícola del valle y descubre sus principales características.": "Explore algumas variedades que contribuíram para o reconhecimento vitivinícola do vale e conheça suas principais características.",
