    "VINO TINTO": "VINHO TINTO",
    "Una de las variedades más representativas de Casablanca. Se caracteriza por sus perfiles frescos y aromáticos, con notas que pueden recordar a cítricos y hierbas.": "Uma das variedades mais representativas de Casablanca. Tem perfil fresco e aromático, com notas que podem lembrar frutas cítricas e ervas.",
    "Fresco y aromático, con posibles notas cítricas y herbáceas.": "Fresco e aromático, com possíveis notas cítricas e herbáceas.",
    "Las características son orientativas y pueden variar según el productor, el viñedo y el método de elaboración.": "As características são indicativas e podem variar conforme o produtor, o vinhedo e o método de produção.",
    "¿Qué vino se adapta a tus gustos?": "Qual vinho combina com seu paladar?",
    "Cada variedad tiene una personalidad diferente. Selecciona dos vinos y descubre sus principales características.": "Cada variedade tem uma personalidade própria. Selecione dois vinhos e conheça suas principais características.",
    "Seleccionar variedad": "Selecionar variedade",
    "Primera variedad": "Primeira variedade",
    "Segunda variedad": "Segunda variedade",
