    "Dos variedades, distintas experiencias": "Duas variedades, experiências diferentes",
    "Las características descritas son orientativas. El perfil de cada vino puede variar según el productor, el clima, la cosecha y el proceso de elaboración.": "As características descritas são indicativas. O perfil de cada vinho pode variar conforme o produtor, o clima, a safra e o processo de produção.",
    "CLIMA, TIERRA Y EXPERIENCIA": "CLIMA, SOLO E EXPERIÊNCIA",
    "El secreto está": "O segredo está",
    "en el territorio.": "no território.",
    "La calidad de un vino no depende de un solo factor. En Casablanca, las condiciones climáticas, el entorno geográfico y el trabajo de sus productores se combinan para dar origen a diferentes estilos y expresiones.": "A qualidade de um vinho não depende de um único fator. Em Casablanca, as condições climáticas, o ambiente geográfico e o trabalho dos produtores se combinam para criar diferentes estilos e expressões.",
    "La influencia marítima puede favorecer la frescura y acidez de ciertas variedades, mientras que las características particulares de cada viñedo aportan matices a sus vinos.": "A influência marítima pode favorecer o frescor e a acidez de algumas variedades, enquanto as características de cada vinhedo acrescentam nuances aos vinhos.",
