    "Conoce la actividad vitivinícola a través de visitas a viñas y experiencias ofrecidas por sus establecimientos.": "Conheça a atividade vitivinícola em visitas a vinícolas e experiências oferecidas pelos estabelecimentos locais.",
    "Naturaleza": "Natureza",
