  "wines.meta.title": "Valle y viñas | Casablanca Chile",
  "wines.meta.description": "Conoce el Valle de Casablanca: su clima costero, paisajes, variedades de vino, tradición vitivinícola y experiencias.",
  "wines.hero.imageAlt": "Paisaje del Valle de Casablanca",
  "wines.hero.eyebrow": "VALLE · VINO · NATURALEZA",
  "wines.hero.title": "El carácter",
  "wines.hero.titleItalic": "del valle.",
  "wines.hero.description": "Un territorio donde la influencia del océano, la naturaleza y la tradición vitivinícola dan forma a un paisaje único.",
  "wines.hero.cta": "Descubrir el valle",
  "wines.identity.eyebrow": "UNA IDENTIDAD RECONOCIDA",
  "wines.identity.title": "Mucho más que",
  "wines.identity.titleSecond": "una copa de vino.",
  "wines.identity.paragraphOne": "Ubicado en la Región de Valparaíso, el Valle de Casablanca se ha consolidado como uno de los territorios vitivinícolas más reconocidos de Chile, especialmente por la producción de vinos de clima fresco.",
  "wines.identity.paragraphTwo": "Su identidad está estrechamente relacionada con la cercanía del océano Pacífico, sus paisajes de colinas y la actividad agrícola que forma parte de la historia de la comuna.",
  "wines.identity.paragraphThree": "Aquí, la vitivinicultura convive con la gastronomía, la naturaleza y las tradiciones del mundo rural.",
  "wines.territory.imageAlt": "Viñedos y colinas del Valle de Casablanca",
  "wines.territory.eyebrow": "EL VALLE Y SU ENTORNO",
  "wines.territory.title": "La influencia",
  "wines.territory.titleSecond": "del océano.",
  "wines.territory.paragraphOne": "Una de las características más importantes del Valle de Casablanca es su proximidad al océano Pacífico. Esta influencia marítima contribuye a moderar las temperaturas y generar condiciones favorables para el cultivo de variedades que se desarrollan mejor en climas frescos.",
  "wines.territory.paragraphTwo": "Las mañanas frescas, las neblinas costeras y las diferencias de temperatura durante el día forman parte de las condiciones que distinguen a este territorio.",
  "wines.territory.paragraphThree": "Estas características pueden favorecer una maduración más pausada de las uvas y la conservación de su acidez natural, cualidades especialmente apreciadas en determinados estilos de vinos blancos y tintos.",
  "wines.features.eyebrow": "UN TERRITORIO CON PERSONALIDAD",
  "wines.features.title": "¿Qué hace especial al valle?",
  "wines.features.description": "La combinación de factores naturales y el trabajo vitivinícola han contribuido a construir la identidad de Casablanca.",
  "wines.features.coastalClimate.title": "Clima costero",
  "wines.features.coastalClimate.description": "La cercanía del océano Pacífico ayuda a moderar las temperaturas, creando condiciones adecuadas para variedades de clima fresco.",
  "wines.features.morningFog.title": "Neblinas matinales",
  "wines.features.morningFog.description": "La presencia de nieblas y mañanas frescas forma parte del entorno climático que caracteriza a distintos sectores del valle.",
  "wines.features.soilDiversity.title": "Diversidad de suelos",
  "wines.features.soilDiversity.description": "Los distintos terrenos y condiciones de cultivo permiten que cada sector presente características particulares para el desarrollo de las vides.",
  "wines.features.winemaking.title": "Tradición vitivinícola",
  "wines.features.winemaking.description": "La experiencia de sus productores y el desarrollo de técnicas de cultivo y elaboración han fortalecido la identidad del valle.",
  "wines.varieties.imageAlt": "Viñedos del Valle de Casablanca",
  "wines.varieties.eyebrow": "VINO Y TERRITORIO",
  "wines.varieties.title": "Sabores que expresan",
  "wines.varieties.titleSecond": "el paisaje.",
  "wines.varieties.paragraphOne": "Casablanca destaca especialmente por sus variedades blancas, aunque también cuenta con una producción de vinos tintos que aprovecha las condiciones de sus distintos sectores.",
  "wines.varieties.paragraphTwo": "Cada variedad posee características propias y puede expresar diferentes aromas, sabores y estructuras dependiendo del clima, el suelo y el proceso de elaboración.",
