  "wines.meta.title": "Casablanca Valley and Wineries | Casablanca Chile",
  "wines.meta.description": "Discover the Casablanca Valley: its coastal climate, landscapes, wine varieties, winemaking tradition and experiences.",
  "wines.hero.imageAlt": "Landscape of the Casablanca Valley",
  "wines.hero.eyebrow": "VALLEY · WINE · NATURE",
  "wines.hero.title": "The character",
  "wines.hero.titleItalic": "of the valley.",
  "wines.hero.description": "A region where ocean influences, nature and winemaking traditions come together to shape a distinctive landscape.",
  "wines.hero.cta": "Discover the valley",
  "wines.identity.eyebrow": "A RECOGNISED WINE REGION",
  "wines.identity.title": "More than",
  "wines.identity.titleSecond": "a glass of wine.",
  "wines.identity.paragraphOne": "Located in the Valparaíso Region, the Casablanca Valley has become one of Chile's best-known wine regions, particularly for its cool-climate wines.",
  "wines.identity.paragraphTwo": "Its identity is closely tied to the Pacific Ocean, its rolling hills and the agricultural activity that has long been part of the commune's history.",
  "wines.identity.paragraphThree": "Here, winemaking sits alongside gastronomy, nature and rural traditions.",
  "wines.territory.imageAlt": "Vineyards and hills in the Casablanca Valley",
  "wines.territory.eyebrow": "THE VALLEY AND ITS SURROUNDINGS",
  "wines.territory.title": "The influence",
  "wines.territory.titleSecond": "of the ocean.",
  "wines.territory.paragraphOne": "One of the Casablanca Valley's defining features is its proximity to the Pacific Ocean. This maritime influence helps moderate temperatures and creates favourable conditions for grape varieties that thrive in cooler climates.",
  "wines.territory.paragraphTwo": "Cool mornings, coastal fog and variations in temperature throughout the day are among the conditions that distinguish this region.",
  "wines.territory.paragraphThree": "These conditions can encourage slower grape ripening and help preserve natural acidity—qualities especially valued in certain styles of white and red wine.",
  "wines.features.eyebrow": "A REGION WITH A DISTINCT CHARACTER",
  "wines.features.title": "What makes the valley special?",
  "wines.features.description": "A combination of natural factors and generations of winemaking have helped shape Casablanca's identity.",
  "wines.features.coastalClimate.title": "Coastal climate",
  "wines.features.coastalClimate.description": "The Pacific Ocean helps moderate temperatures, creating suitable conditions for cool-climate grape varieties.",
  "wines.features.morningFog.title": "Morning fog",
  "wines.features.morningFog.description": "Fog and cool mornings are part of the climatic conditions that shape different parts of the valley.",
  "wines.features.soilDiversity.title": "Diverse soils",
  "wines.features.soilDiversity.description": "Different soils and growing conditions give each area its own characteristics for vine cultivation.",
  "wines.features.winemaking.title": "A winemaking tradition",
  "wines.features.winemaking.description": "The experience of local producers and the development of growing and winemaking techniques have strengthened the valley's identity.",
