  "history.point.foundation.title": "La fundación de Casablanca",
  "history.point.foundation.description": "El 23 de octubre de 1753, durante el gobierno de Domingo Ortiz de Rozas, se fundó la Villa de Santa Bárbara de la Reina de Casablanca, nombre otorgado en honor a Bárbara de Braganza, esposa del rey Fernando VI de España. Su trazado original siguió el modelo de cuadrícula utilizado en las ciudades hispanoamericanas de la época.",
