  "attractions.detail.loVasquez.introduction": "Um dos locais de peregrinação mais importantes do Chile, o Santuário de Lo Vásquez é um espaço de devoção que recebe milhares de fiéis e visitantes todos os anos.",
  "attractions.detail.loVasquez.section1Title": "Um lugar de fé e tradição",
  "attractions.detail.loVasquez.section1Text": "No santuário é venerada a imagem da Imaculada Conceição da Virgem Maria. Sua importância religiosa se manifesta especialmente na celebração anual de 8 de dezembro, quando peregrinos chegam de diferentes partes do país.",
  "attractions.detail.loVasquez.section2Title": "A celebração de 8 de dezembro",
