  "attractions.detail.tunquen.category": "NATUREZA E CONSERVAÇÃO",
  "attractions.detail.tunquen.title": "Tunquén: praia e área úmida",
  "attractions.detail.tunquen.alt": "Praia e área úmida de Tunquén",
  "attractions.detail.tunquen.introduction": "Um destino costeiro tranquilo, marcado pela natureza. A praia de Tunquén se destaca por sua extensão, suas areias e dunas naturais. Nas proximidades, o Santuário da Natureza da Área Úmida de Tunquén protege um ecossistema de grande valor para a biodiversidade local.",
  "attractions.detail.tunquen.section1Title": "Uma paisagem para contemplar",
  "attractions.detail.tunquen.section1Text": "A praia e seus arredores naturais reúnem o mar, as dunas e as áreas úmidas em um mesmo território. É um lugar que convida a caminhar, apreciar a paisagem e aproveitar a natureza.",
  "attractions.detail.tunquen.section2Title": "Um ecossistema que devemos proteger",
  "attractions.detail.tunquen.section2Text": "O Santuário da Natureza da Área Úmida de Tunquén protege ambientes costeiros e diversas espécies de flora e fauna. Sua conservação também depende do cuidado de quem visita o local.",
  "attractions.detail.tunquen.recommendationsTitle": "Informações para visitantes",
  "attractions.detail.tunquen.recommendation1": "Informe-se sobre as condições de acesso antes da visita.",
  "attractions.detail.tunquen.recommendation2": "Respeite as trilhas e as áreas de conservação.",
  "attractions.detail.tunquen.recommendation3": "Siga as orientações da administração do santuário.",
  "attractions.detail.tunquen.rulesTitle": "Recomendações para uma visita responsável",
  "attractions.detail.tunquen.rulesIntroduction": "O folheto informativo da área úmida apresenta as seguintes recomendações para proteger a flora, a fauna e o ambiente:",
  "attractions.detail.tunquen.rule1": "Não entre com animais de estimação.",
  "attractions.detail.tunquen.rule2": "Não voe drones.",
  "attractions.detail.tunquen.rule3": "Não cace nem capture animais.",
  "attractions.detail.tunquen.rule4": "Não pratique esportes aquáticos.",
  "attractions.detail.tunquen.rule5": "Siga sempre os caminhos e as trilhas sinalizados.",
  "attractions.detail.tunquen.rule6": "Faça o percurso a pé.",
  "attractions.detail.tunquen.rule7": "Evite tocar música ou fazer muito barulho.",
  "attractions.detail.tunquen.rule8": "Não acenda fogo nem provoque situações que possam causar incêndios.",
  "attractions.detail.tunquen.rule9": "Leve consigo todo o lixo e os resíduos.",
  "attractions.detail.tunquen.rule10": "Não acampe.",
  "attractions.detail.tunquen.note": "Estas recomendações foram transcritas do folheto informativo compartilhado. Consulte o site oficial para verificar as condições de acesso e as orientações vigentes.",
  "attractions.detail.tunquen.link1": "Site oficial da área úmida",
  "attractions.detail.tunquen.link2": "Santuário no Instagram",

  "attractions.detail.lagunillas.category": "PATRIMÔNIO RURAL",
