  "attractions.detail.lagunillas.introduction": "Lagunillas é uma localidade do município de Casablanca que preserva uma forte identidade rural, expressa em sua arquitetura tradicional, construções patrimoniais e história local.",
  "attractions.detail.lagunillas.section1Title": "Uma localidade com identidade própria",
  "attractions.detail.lagunillas.section1Text": "A paisagem e a arquitetura revelam aspectos da vida rural tradicional. Casas e outras construções patrimoniais preservam parte da história arquitetônica da localidade.",
  "attractions.detail.lagunillas.section2Title": "Igreja Nuestra Señora de las Mercedes",
  "attractions.detail.lagunillas.section2Text": "A Igreja Nuestra Señora de las Mercedes é um dos principais marcos patrimoniais de Lagunillas e faz parte da identidade histórica e cultural da comunidade.",
  "attractions.detail.lagunillas.recommendationsTitle": "Informações para visitantes",
