  "history.point.foundation.description": "Em 23 de outubro de 1753, durante o governo de Domingo Ortiz de Rozas, foi fundada a Villa de Santa Bárbara de la Reina de Casablanca. O nome homenageia Bárbara de Braganza, esposa do rei Fernando VI da Espanha. Seu traçado original seguia o plano em quadras utilizado nas cidades hispano-americanas da época.",
  "history.point.foundation.imageAlt": "Fotografia histórica de Casablanca",
  "history.point.foundation.kicker": "23 DE OUTUBRO DE 1753",
  "history.point.square.title": "A Plaza de Armas e as origens da cidade",
  "history.point.square.description": "A praça faz parte do centro histórico de Casablanca. A cidade surgiu ao lado da antiga igreja, e seu traçado original foi desenhado por Joseph Bañado y Gracia. Com o tempo, esse espaço central se consolidou como ponto de encontro da vida comunitária.",
  "history.point.square.imageAlt": "Plaza de Armas de Casablanca",
  "history.point.square.kicker": "O CENTRO DA VIDA COMUNITÁRIA",
  "history.point.museum.title": "Museu Arqueológico e Antropológico",
  "history.point.museum.description": "Este museu preserva uma parte importante da memória do território. Seu acervo inclui peças arqueológicas associadas às culturas Bato, Aconcagua e Inca, além de materiais paleontológicos e históricos relacionados à vida rural e ao desenvolvimento de Casablanca.",
  "history.point.museum.imageAlt": "Museu Arqueológico e Antropológico de Casablanca",
  "history.point.museum.kicker": "ARQUEOLOGIA, CULTURA E MEMÓRIA"
